class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        vector<bool> seen(k + 1, false);
        int collected = 0, n = nums.size();
        for (int i = n - 1; i >= 0; i--) {
            if (nums[i] <= k && !seen[nums[i]]) {
                seen[nums[i]] = true;
                collected++;
            }
            if (collected == k) return n - i;
        }
        return n;
    }
};

class Solution {
    public int minOperations(List<Integer> nums, int k) {
        boolean[] seen = new boolean[k + 1];
        int collected = 0, n = nums.size();
        for (int i = n - 1; i >= 0; i--) {
            int x = nums.get(i);
            if (x <= k && !seen[x]) {
                seen[x] = true;
                collected++;
            }
            if (collected == k) return n - i;
        }
        return n;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
