var minOperations = function(nums, k) {
    const seen = new Set();
    const n = nums.length;
    for (let i = n - 1; i >= 0; i--) {
        if (nums[i] <= k) seen.add(nums[i]);
        if (seen.size === k) return n - i;
    }
    return n;
};
